use vstd::prelude::*;

verus! {
    /// Given a vector `a`, returns a fresh vector of the same length,
    /// all of whose entries are zero.
    fn zeros_like(a: &Vec<i32>) -> (b: Vec<i32>)
        ensures
            // length is preserved
            b.len() == a.len(),
            // every entry is 0
            forall |i: nat| i < a.len() as nat ==> b.view()[i] == 0,
    {
        vec![0; a.len()]
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let a: Vec<i32> = Vec::new();
        let z = zeros_like(&a);
        assert_eq!(z.len(), 0);
    }

    #[test]
    fn test_non_empty() {
        let a = vec![1, -2, 3, 4];
        let z = zeros_like(&a);
        // length matches
        assert_eq!(z.len(), a.len());
        // all elements are zero
        assert!(z.iter().all(|&x| x == 0));

        // property: x + 0 == x and 0 + x == x
        let b = vec![10, 20, 30, 40];
        let sum_left: Vec<i32>  = b.iter().zip(&z).map(|(&x, &y)| x + y).collect();
        let sum_right: Vec<i32> = z.iter().zip(&b).map(|(&x, &y)| x + y).collect();
        assert_eq!(sum_left, b);
        assert_eq!(sum_right, b);
    }
}